/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3column {	public static final class Attr {		public static final String columns = "columns";		public static final String count = "column-count";		public static final String gap = "column-gap";		public static final String span = "column-span";		public static final String width = "column-width";		public static final String rule = "column-rule";		public static final String ruleWidth = "column-rule-width";		public static final String ruleStyle = "column-rule-style";		public static final String ruleColor = "column-rule-color";	}	public Value columns(String width, int count) {		return new Value().name(Attr.columns).text(String.format("%s %d", width, count));	}	public Value count(int number) {		return new Value().name(Attr.count).text(String.valueOf(number));	}	public Value gap(String pixels) {		return new Value().name(Attr.gap).text(pixels);	}	public Value span(boolean all) {		String value = all ? "all" : "none";		return new Value().name(Attr.span).text(value);	}	public Value width(String pixels) {		return new Value().name(Attr.width).text(pixels);	}	public Value rule(String shorthand) {		return new Value().name(Attr.rule).text(shorthand);	}	public Value ruleWidth(String pixels) {		return new Value().name(Attr.ruleWidth).text(pixels);	}	public Value ruleStyle(String style) {		return new Value().name(Attr.ruleStyle).text(style);	}	public Value ruleColor(String color) {		return new Value().name(Attr.ruleColor).text(color);	}}